    # Calculate the number of multiples of K up to N
    count_multiples = (N // K) + 1

    # Initialize a 2D list to store the count of pairs (a, b) such that (a + b) % K == 0
    pair_count = [[0] * count_multiples for _ in range(count_multiples)]

    # Fill the pair_count table
    for a in range(1, count_multiples):
        for b in range(1, count_multiples):
            if (a * K + b * K) % K == 0:
                pair_count[a][b] += 1

    # Calculate the number of triples (a, b, c)
    total_triples = 0
    for a in range(1, count_multiples):
        for b in range(1, count_multiples):
            c = (K - (a * K + b * K) % K) % K
            if c < count_multiples:
                total_triples += pair_count[a][b]

    return total_triples

